import random

heads_checked = 0
tails_checked = 0

def flip_coin():
    return random.choice(['Heads', 'Tails'])

def is_heads(result):
    global heads_checked
    heads_checked += 1
    return result == 'Heads'

def is_tails(result):
    global tails_checked
    tails_checked += 1
    return result == 'Tails'

def coin_game():
    result = flip_coin()
    if is_heads(result) or is_tails(result):
        if result == 'Heads':
            return 'Got heads!'
        else:
            return 'Got tails!'

